// Authored wrapper; sibling bundles are generated by vendor:formatter.
export async function formatCode(source, language, cursorOffset = 0) {
  const parsers = { java: 'java', javascript: 'babel', typescript: 'typescript' };
  if (!Object.hasOwn(parsers, language)) throw new Error('暂不支持此语言的格式化。');
  let prettier, plugins;
  try {
    prettier = await import('./prettier.js');
    plugins = language === 'java' ? [await import('./java.js')]
      : await Promise.all([import(language === 'javascript' ? './babel.js' : './typescript.js'), import('./estree.js')]);
  } catch {
    throw new Error('格式化器加载失败，请刷新后重试。');
  }
  try {
    const result = await prettier.formatWithCursor(source, {
      parser: parsers[language], plugins: plugins.map(plugin => plugin.default || plugin), cursorOffset,
      tabWidth: 4, useTabs: false, printWidth: 100, endOfLine: 'lf',
    });
    return { formatted: result.formatted, cursorOffset: result.cursorOffset };
  } catch {
    throw new Error('无法格式化，请检查代码是否完整、语法是否正确。原草稿未修改。');
  }
}
